import type { HbrPopover } from "../popover/popover";

type ChartPopoverOptions = Partial<HbrPopover> & {
	/** Lets the popover manage its own open and close behavior. */
	selfManaged?: boolean;
};

const isChartPopoverSelfManaged = (
	supportsSelfManaged: boolean,
	popoverOptions?: ChartPopoverOptions,
	override?: ChartPopoverOptions,
) =>
	supportsSelfManaged &&
	(override?.selfManaged ?? popoverOptions?.selfManaged ?? false);

const resolveChartPopoverOptions = (
	defaults: Partial<HbrPopover>,
	popoverOptions: ChartPopoverOptions | undefined,
	supportsSelfManaged: boolean,
	override?: ChartPopoverOptions,
): Partial<HbrPopover> => {
	const { selfManaged: _selfManaged, ...resolvedPopoverOptions } =
		popoverOptions ?? {};
	const { selfManaged: _overrideSelfManaged, ...resolvedOverride } =
		override ?? {};
	const selfManaged = isChartPopoverSelfManaged(
		supportsSelfManaged,
		popoverOptions,
		override,
	);

	return {
		...defaults,
		...(supportsSelfManaged
			? { trigger: selfManaged ? "hover" : "click" }
			: {}),
		...resolvedPopoverOptions,
		...(supportsSelfManaged ? resolvedOverride : {}),
	};
};

const applyChartPopoverOptions = (
	popover: HTMLHbrPopoverElement | undefined,
	popoverOptions: Partial<HbrPopover>,
) => {
	if (!popover) {
		return;
	}

	Object.entries(popoverOptions).forEach(([key, value]) => {
		if (value !== undefined) {
			Reflect.set(popover, key, value);
		}
	});
};

export {
	applyChartPopoverOptions,
	type ChartPopoverOptions,
	isChartPopoverSelfManaged,
	resolveChartPopoverOptions,
};
